import React, { useState, useEffect } from "react";

function RecipeGenerator() {
  // --- State Variables ---
  const [darkMode, setDarkMode] = useState(false);
  const [mode, setMode] = useState("ingredients"); // "ingredients" or "name"
  const [recipeName, setRecipeName] = useState("");
  const [ingredients, setIngredients] = useState("");
  const [mealType, setMealType] = useState("Breakfast");
  const [cuisine, setCuisine] = useState("");
  const [cookingTime, setCookingTime] = useState("Less than 30 minutes");
  const [complexity, setComplexity] = useState("Beginner");
  const [recipes, setRecipes] = useState([]); // Should hold structured recipe objects
  const [error, setError] = useState(null);
  const [loading, setLoading] = useState(false);

  // --- Effects ---
  // Effect to toggle dark mode class on the document element
  useEffect(() => {
    if (darkMode) {
      document.documentElement.classList.add("dark");
    } else {
      document.documentElement.classList.remove("dark");
    }
  }, [darkMode]);

  // --- Helper Functions ---
  // Clean text by removing asterisks and trimming whitespace
  const cleanText = (text) => {
    if (typeof text === "string") {
      return text.replace(/\*/g, "").trim();
    }
    // Return non-string inputs as is
    return text;
  };

  // Unified handler for API responses - expects structured JSON
  const handleApiResponse = (data) => {
    console.log("Received data from backend:", data); // Log the raw response

    // Handle potential backend errors embedded in the response body
    if (data.error) {
      throw new Error(data.error);
    }

    // Expecting data.recipe to be an object or an array of objects
    if (
      data.recipe &&
      (typeof data.recipe === "object" || Array.isArray(data.recipe))
    ) {
      // Normalize to an array even if a single object is returned
      const normalizedRecipes = Array.isArray(data.recipe)
        ? data.recipe
        : [data.recipe];

      // Process and clean each recipe object
      const processedRecipes = normalizedRecipes
        .map((recipe) => {
          // Ensure recipe is an object before accessing properties
          if (typeof recipe !== "object" || recipe === null) {
            console.warn("Skipping invalid recipe data:", recipe);
            return null; // Skip invalid entries
          }
          return {
            title: cleanText(recipe.title) || "Untitled Recipe", // Provide fallback title
            ingredients: Array.isArray(recipe.ingredients)
              ? recipe.ingredients.map(cleanText)
              : [], // Ensure ingredients is an array
            equipment: Array.isArray(recipe.equipment)
              ? recipe.equipment.map(cleanText)
              : [], // Ensure equipment is an array
            instructions: Array.isArray(recipe.instructions)
              ? recipe.instructions.map(cleanText)
              : [], // Ensure instructions is an array
            tips: Array.isArray(recipe.tips) ? recipe.tips.map(cleanText) : [], // Ensure tips is an array
          };
        })
        .filter((recipe) => recipe !== null); // Filter out any null entries from invalid data

      if (processedRecipes.length > 0) {
        setRecipes(processedRecipes); // Update state with the processed array
        setError(null); // Clear any previous errors
      } else {
        console.warn(
          "Backend returned recipe data, but it was empty or invalid after processing."
        );
        setRecipes([]);
        setError("No valid recipe data received from the backend."); // Set a specific error if data processing fails
      }
    } else {
      console.warn(
        "Received unexpected data format or empty recipe field:",
        data
      );
      // Handle cases where backend might return unexpected format or missing recipe field
      setRecipes([]); // Clear recipes
      setError("Received unexpected recipe data format from the backend."); // Inform the user
    }
  };

  // --- API Submission Handlers ---
  const handleSubmitByName = async () => {
    if (!recipeName.trim()) {
      // Use trim() to check for empty string after whitespace removal
      setError("Please enter a recipe name.");
      setRecipes([]); // Clear previous recipes
      return;
    }
    setLoading(true);
    setError(null); // Clear previous errors
    setRecipes([]); // Clear previous recipes
    try {
      const response = await fetch(
        "http://localhost:5000/api/generate-by-name", // Ensure your backend URL is correct
        {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ recipeName: recipeName.trim() }), // Send trimmed value
        }
      );

      // Check for non-OK HTTP status codes
      if (!response.ok) {
        // Attempt to read error message from backend response body
        const errorData = await response.json().catch(() => ({})); // Catch JSON parse error
        throw new Error(
          `HTTP error! status: ${response.status} - ${
            errorData.error || response.statusText
          }`
        );
      }

      const data = await response.json();
      handleApiResponse(data); // Use the common handler
    } catch (err) {
      console.error("Error generating recipe by name:", err);
      setError(`Failed to generate recipe by name: ${err.message}`);
      setRecipes([]); // Clear recipes on error
    } finally {
      setLoading(false);
    }
  };

  const handleSubmitByIngredients = async () => {
    if (!ingredients.trim()) {
      // Use trim()
      setError("Please enter ingredients.");
      setRecipes([]); // Clear previous recipes
      return;
    }

    setLoading(true);
    setError(null); // Clear previous errors
    setRecipes([]); // Clear previous recipes
    try {
      const response = await fetch("http://localhost:5000/api/generate", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          ingredients: ingredients.trim(), // Send trimmed value
          mealType,
          cuisine: cuisine.trim(), // Send trimmed value
          cookingTime,
          complexity,
        }),
      });

      // Check for non-OK HTTP status codes
      if (!response.ok) {
        const errorData = await response.json().catch(() => ({}));
        throw new Error(
          `HTTP error! status: ${response.status} - ${
            errorData.error || response.statusText
          }`
        );
      }

      const data = await response.json();
      handleApiResponse(data); // Use the common handler
    } catch (err) {
      console.error("Error generating recipe by ingredients:", err);
      setError(`Failed to generate recipe by ingredients: ${err.message}`);
      setRecipes([]); // Clear recipes on error
    } finally {
      setLoading(false);
    }
  };

  // Main submit handler chooses which specific handler to call
  const handleSubmit = () => {
    if (mode === "name") {
      handleSubmitByName();
    } else {
      handleSubmitByIngredients();
    }
  };

  // --- Render ---
  return (
    <div
      className={`min-h-screen bg-gradient-to-b ${
        darkMode ? "from-gray-900 to-gray-800" : "from-white to-gray-100"
      } flex items-center justify-center p-4 transition-colors duration-300 text-gray-800 dark:text-white`}
      // Removed overflow-hidden from the main container
    >
      {/* Dark Mode Toggle */}
      <div className="absolute top-4 right-4 flex space-x-2 z-10">
        {" "}
        {/* Added z-10 */}
        <button
          onClick={() => setDarkMode(!darkMode)}
          className="bg-gray-800 dark:bg-white text-white dark:text-black px-4 py-2 rounded shadow hover:opacity-80"
          aria-label={darkMode ? "Switch to Light Mode" : "Switch to Dark Mode"}
        >
          {darkMode ? "☀️" : "🌙"}
        </button>
      </div>
      {/* Main Content Grid */}
      {/* Removed height calc from grid container, panels will define their own height */}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-6 w-full max-w-6xl h-full">
        {" "}
        {/* Changed h-[calc(100vh-2rem)] to h-full */}
        {/* LEFT - Recipe Generator Panel */}
        <div className="bg-white dark:bg-gray-700 dark:text-white rounded-xl shadow-lg p-6 flex flex-col h-full overflow-y-auto">
          {" "}
          {/* Added shadow-lg and overflow-y-auto, h-full */}
          <h2 className="text-2xl font-bold text-center mb-6">
            Recipe Generator
          </h2>
          {/* Mode Switch */}
          <div className="mb-6 flex justify-center">
            <label className="flex items-center space-x-2 cursor-pointer">
              <span className="text-gray-800 dark:text-white">
                By Ingredients
              </span>
              <input
                type="checkbox"
                checked={mode === "name"}
                onChange={() =>
                  setMode(mode === "ingredients" ? "name" : "ingredients")
                }
                className="toggle-checkbox"
                aria-label="Switch between generating by ingredients or by name"
              />
              <span className="toggle-switch"></span>
              <span className="text-gray-800 dark:text-white">By Name</span>
            </label>
            {/* Toggle switch styles - Kept inline for simplicity */}
            <style>{`
              .toggle-checkbox { display: none; }
              .toggle-switch { width: 40px; height: 20px; background-color: #ccc; border-radius: 10px; position: relative; cursor: pointer; transition: background-color 0.3s; }
              .toggle-checkbox:checked + .toggle-switch { background-color: #4b9af4; }
              .toggle-switch::after { content: ''; width: 16px; height: 16px; background-color: white; border-radius: 50%; position: absolute; top: 2px; left: 2px; transition: transform 0.3s; }
              .toggle-checkbox:checked + .toggle-switch::after { transform: translateX(20px); }
            `}</style>
          </div>
          {/* Conditional Fields Area - flex-grow to take available space, enabling panel scroll */}
          <div className="flex-grow space-y-4 overflow-y-auto pr-2">
            {" "}
            {/* Added flex-grow, overflow-y-auto, pr-2 */}
            {mode === "ingredients" ? (
              <>
                {/* Group 1 */}
                <div className="space-y-4">
                  <div>
                    <label
                      className="block font-semibold mb-1"
                      htmlFor="ingredients"
                    >
                      Ingredients*
                    </label>
                    <input
                      id="ingredients"
                      type="text"
                      className="w-full border dark:border-gray-600 rounded px-3 py-2 bg-white dark:bg-gray-800 dark:text-white focus:ring-2 focus:ring-blue-500 outline-none"
                      placeholder="e.g. tomato, potato, onion"
                      value={ingredients}
                      onChange={(e) => setIngredients(e.target.value)}
                      required // Mark as required
                    />
                  </div>
                  <div>
                    <label
                      className="block font-semibold mb-1"
                      htmlFor="mealType"
                    >
                      Meal Type
                    </label>
                    <select
                      id="mealType"
                      className="w-full border dark:border-gray-600 rounded px-3 py-2 bg-white dark:bg-gray-800 dark:text-white focus:ring-2 focus:ring-blue-500 outline-none"
                      value={mealType}
                      onChange={(e) => setMealType(e.target.value)}
                    >
                      <option>Breakfast</option>
                      <option>Lunch</option>
                      <option>Dinner</option>
                      <option>Snack</option>
                      <option>Dessert</option>
                    </select>
                  </div>
                </div>
                {/* Group 2 */}
                <div className="space-y-4">
                  <div>
                    <label
                      className="block font-semibold mb-1"
                      htmlFor="cuisine"
                    >
                      Cuisine Preference
                    </label>
                    <input
                      id="cuisine"
                      type="text"
                      className="w-full border dark:border-gray-600 rounded px-3 py-2 bg-white dark:bg-gray-800 dark:text-white focus:ring-2 focus:ring-blue-500 outline-none"
                      placeholder="e.g. Indian, Italian (optional)"
                      value={cuisine}
                      onChange={(e) => setCuisine(e.target.value)}
                    />
                  </div>
                  <div>
                    <label
                      className="block font-semibold mb-1"
                      htmlFor="cookingTime"
                    >
                      Cooking Time
                    </label>
                    <select
                      id="cookingTime"
                      className="w-full border dark:border-gray-600 rounded px-3 py-2 bg-white dark:bg-gray-800 dark:text-white focus:ring-2 focus:ring-blue-500 outline-none"
                      value={cookingTime}
                      onChange={(e) => setCookingTime(e.target.value)}
                    >
                      <option>Less than 30 minutes</option>
                      <option>30-60 minutes</option>
                      <option>More than 1 hour</option>
                    </select>
                  </div>
                </div>
                {/* Group 3 */}
                <div>
                  <label
                    className="block font-semibold mb-1"
                    htmlFor="complexity"
                  >
                    Complexity
                  </label>
                  <select
                    id="complexity"
                    className="w-full border dark:border-gray-600 rounded px-3 py-2 bg-white dark:bg-gray-800 dark:text-white focus:ring-2 focus:ring-blue-500 outline-none"
                    value={complexity}
                    onChange={(e) => setComplexity(e.target.value)}
                  >
                    <option>Beginner</option>
                    <option>Intermediate</option>
                    <option>Advanced</option>
                  </select>
                </div>
              </>
            ) : (
              // Mode === "name"
              <div className="space-y-4">
                <div>
                  <label
                    className="block font-semibold mb-1"
                    htmlFor="recipeName"
                  >
                    Recipe Name*
                  </label>
                  <input
                    id="recipeName"
                    type="text"
                    className="w-full border dark:border-gray-600 rounded px-3 py-2 bg-white dark:bg-gray-800 dark:text-white focus:ring-2 focus:ring-blue-500 outline-none"
                    placeholder="e.g. Classic Margherita Pizza"
                    value={recipeName}
                    onChange={(e) => setRecipeName(e.target.value)}
                    required // Mark as required
                  />
                </div>
              </div>
            )}
          </div>{" "}
          {/* End conditional fields area */}
          {/* Submit Button */}
          <button
            onClick={handleSubmit}
            disabled={
              loading ||
              (mode === "ingredients" && !ingredients.trim()) ||
              (mode === "name" && !recipeName.trim())
            } // Disable if loading or required fields are empty
            className={`bg-blue-600 hover:bg-blue-700 text-white font-bold py-3 px-4 rounded w-full mt-6 transition duration-150 ease-in-out ${
              loading ||
              (mode === "ingredients" && !ingredients.trim()) ||
              (mode === "name" && !recipeName.trim())
                ? "opacity-50 cursor-not-allowed"
                : ""
            }`}
          >
            {loading ? "Generating..." : "Generate Recipe"}{" "}
            {/* Show loading text */}
          </button>
        </div>{" "}
        {/* End Left Panel */}
        {/* RIGHT - Recipe Output Panel */}
        <div className="bg-white dark:bg-gray-700 rounded-xl shadow-lg p-6 flex flex-col h-full">
          {" "}
          {/* Added shadow-lg, h-full */}
          <h2 className="text-2xl font-bold mb-4 text-center text-gray-800 dark:text-white">
            Recipe Details
          </h2>
          {/* Scrollable area for recipe content */}
          {/* This is the key container for scrolling the recipe details */}
          <div className="flex-grow overflow-y-auto pr-2">
            {" "}
            {/* Added flex-grow, overflow-y-auto, pr-2 */}
            {/* Error Display */}
            {error && (
              <p className="text-red-500 dark:text-red-400 text-center mb-4 font-semibold break-words">
                Error: {error}
              </p>
            )}
            {/* Loading Spinner */}
            {loading && (
              <div className="flex items-center justify-center h-full">
                <div className="animate-spin rounded-full h-16 w-16 border-t-4 border-b-4 border-blue-500"></div>{" "}
                {/* Improved spinner */}
              </div>
            )}
            {/* Placeholder message */}
            {!loading && recipes.length === 0 && !error && (
              <p className="text-gray-500 dark:text-gray-400 text-center h-full flex items-center justify-center">
                Your generated recipe will appear here.
              </p>
            )}
            {/* Recipe Display */}
            {!loading && recipes.length > 0 && (
              <div className="space-y-6">
                {" "}
                {/* Increased space between sections */}
                {recipes.map((recipe, index) => (
                  <div
                    key={index}
                    className="text-gray-800 dark:text-gray-200" // Base text colors
                  >
                    {/* Title */}
                    {recipe.title && (
                      <h3 className="text-xl font-bold text-center mb-5 underline decoration-blue-500 decoration-2 underline-offset-4">
                        {" "}
                        {/* Increased font, margin, underline */}
                        {recipe.title}
                      </h3>
                    )}

                    {/* Ingredients Section */}
                    {recipe.ingredients && recipe.ingredients.length > 0 && (
                      <div className="mb-5">
                        {" "}
                        {/* Increased margin */}
                        <h4 className="text-lg font-semibold text-gray-800 dark:text-white mb-2">
                          Ingredients:
                        </h4>
                        <ul className="list-disc list-inside space-y-1 text-sm pl-2">
                          {" "}
                          {/* Switched to ul/disc, added padding */}
                          {recipe.ingredients.map((ing, i) => (
                            <li key={i}>{ing}</li>
                          ))}
                        </ul>
                      </div>
                    )}

                    {/* Equipment Section */}
                    {recipe.equipment && recipe.equipment.length > 0 && (
                      <div className="mb-5">
                        {" "}
                        {/* Increased margin */}
                        <h4 className="text-lg font-semibold text-gray-800 dark:text-white mb-2">
                          Equipment:
                        </h4>
                        <ul className="list-disc list-inside space-y-1 text-sm pl-2">
                          {" "}
                          {/* ul/disc, added padding */}
                          {recipe.equipment.map((eq, i) => (
                            <li key={i}>{eq}</li>
                          ))}
                        </ul>
                      </div>
                    )}

                    {/* Instructions Section - Renders Array */}
                    {recipe.instructions && recipe.instructions.length > 0 && (
                      <div className="mb-5">
                        {" "}
                        {/* Increased margin */}
                        <h4 className="text-lg font-semibold text-gray-800 dark:text-white mb-2">
                          Instructions:
                        </h4>
                        {/* Render instructions as an ordered list */}
                        <ol className="list-decimal list-outside space-y-2 text-sm pl-6 leading-relaxed">
                          {" "}
                          {/* list-outside, added padding, line height */}
                          {recipe.instructions.map((step, i) => (
                            <li key={i}>{step}</li>
                          ))}
                        </ol>
                      </div>
                    )}

                    {/* Tips Section */}
                    {recipe.tips && recipe.tips.length > 0 && (
                      <div className="mb-5">
                        {" "}
                        {/* Increased margin */}
                        <h4 className="text-lg font-semibold text-gray-800 dark:text-white mb-2">
                          Optional Tips & Variations:
                        </h4>
                        <ul className="list-disc list-inside space-y-1 text-sm pl-2">
                          {" "}
                          {/* ul/disc, added padding */}
                          {recipe.tips.map((tip, i) => (
                            <li key={i}>{tip}</li>
                          ))}
                        </ul>
                      </div>
                    )}
                  </div> // End individual recipe render
                ))}
              </div> // End recipes map container
            )}
          </div>{" "}
          {/* End Scrollable Area */}
        </div>{" "}
        {/* End Right Panel */}
      </div>{" "}
      {/* End Main Content Grid */}
      {/* Removed the unused inline style block */}
    </div> // End Page Container
  );
}

export default RecipeGenerator;
